const listActivities = `-- name: ListActivities :many
SELECT id, activity_type, crm_company_id, contact_id, deal_id, actor_user_id, summary, detail, occurred_at, source_module
FROM crm.activities WHERE tenant_id = $1
  AND ($2::uuid IS NULL OR crm_company_id = $2::uuid)
  AND ($3::uuid IS NULL OR deal_id = $3::uuid)
  AND ($4::uuid IS NULL OR contact_id = $4::uuid)
ORDER BY occurred_at DESC, id DESC LIMIT 200
`

type ListActivitiesParams struct {
	TenantID     uuid.UUID
	CrmCompanyID *uuid.UUID
	DealID       *uuid.UUID
	ContactID    *uuid.UUID
}

type ListActivitiesRow struct {
	ID           uuid.UUID
	ActivityType string
	CrmCompanyID *uuid.UUID
	ContactID    *uuid.UUID
	DealID       *uuid.UUID
	ActorUserID  *uuid.UUID
	Summary      string
	Detail       []byte
	OccurredAt   time.Time
	SourceModule *string
}

func (q *Queries) ListActivities(ctx context.Context, arg ListActivitiesParams) ([]ListActivitiesRow, error) {
	rows, err := q.db.Query(ctx, listActivities,
		arg.TenantID,
		arg.CrmCompanyID,
		arg.DealID,
		arg.ContactID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListActivitiesRow
	for rows.Next() {
		var i ListActivitiesRow
		if err := rows.Scan(
			&i.ID,
			&i.ActivityType,
			&i.CrmCompanyID,
			&i.ContactID,
			&i.DealID,
			&i.ActorUserID,
			&i.Summary,
			&i.Detail,
			&i.OccurredAt,
			&i.SourceModule,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

