const updateTask = `-- name: UpdateTask :execrows
UPDATE crm.tasks SET title = coalesce($1, title), description = coalesce($2, description),
  assignee_user_id = CASE WHEN $3::bool THEN $4 ELSE assignee_user_id END,
  due_at = CASE WHEN $5::bool THEN $6 ELSE due_at END,
  status = coalesce($7, status), completed_at = CASE WHEN $7::text = 'done' THEN now() WHEN $7::text IS NOT NULL THEN NULL ELSE completed_at END
WHERE tenant_id = $8 AND id = $9 AND deleted_at IS NULL
`

type UpdateTaskParams struct {
	Title          *string
	Description    *string
	SetAssignee    bool
	AssigneeUserID *uuid.UUID
	SetDue         bool
	DueAt          *time.Time
	Status         *string
	TenantID       uuid.UUID
	ID             uuid.UUID
}

func (q *Queries) UpdateTask(ctx context.Context, arg UpdateTaskParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateTask,
		arg.Title,
		arg.Description,
		arg.SetAssignee,
		arg.AssigneeUserID,
		arg.SetDue,
		arg.DueAt,
		arg.Status,
		arg.TenantID,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
